"""Request and response schemas (Pydantic). These validate all API input."""

import uuid

from pydantic import BaseModel, field_validator

MAX_MESSAGE_LENGTH = 2000


def validate_session_id(value: str) -> str:
    """Session IDs are UUIDs generated by the server; anything else is rejected."""
    try:
        return str(uuid.UUID(value))
    except (ValueError, AttributeError, TypeError):
        raise ValueError("Invalid session ID format.") from None


def _clean_text(value: str, label: str) -> str:
    value = (value or "").strip()
    if not value:
        raise ValueError(f"{label} cannot be empty.")
    if len(value) > MAX_MESSAGE_LENGTH:
        raise ValueError(f"{label} is too long (maximum {MAX_MESSAGE_LENGTH} characters).")
    return value


class ChatRequest(BaseModel):
    message: str
    session_id: str | None = None

    @field_validator("message")
    @classmethod
    def _check_message(cls, v: str) -> str:
        return _clean_text(v, "Message")

    @field_validator("session_id")
    @classmethod
    def _check_session(cls, v: str | None) -> str | None:
        return validate_session_id(v) if v else None


class ChatResponse(BaseModel):
    reply: str
    session_id: str
    is_crisis: bool = False


class DocumentQueryRequest(BaseModel):
    question: str

    @field_validator("question")
    @classmethod
    def _check_question(cls, v: str) -> str:
        return _clean_text(v, "Question")


class SourceInfo(BaseModel):
    file: str
    page: str | None = None
    score: float | None = None
    snippet: str


class DocumentQueryResponse(BaseModel):
    answer: str
    found: bool
    is_crisis: bool = False
    sources: list[SourceInfo] = []


class DocumentStatus(BaseModel):
    count: int
    documents: list[str]
    indexed: bool


class HealthResponse(BaseModel):
    status: str
    version: str
    ai_configured: bool
    active_sessions: int
